head.script:
function essOpenWorkspace(targetTab, moduleName) {
    var hub = document.getElementById('ess_level_hub');
    var ws = document.getElementById('ess_level_workspace');
    var headerTitle = document.getElementById('ess_top_header_title');

    if (hub) hub.style.display = 'none';
    if (ws) ws.style.display = 'flex';

    var tab = targetTab || 'tab_dashboard';
    var name = moduleName || localStorage.getItem('ess_module_title') || 'الخدمة الذاتية';

    if (headerTitle) {
        headerTitle.innerText = name;
    }

    if (tab === 'tab_dashboard' && window.location.pathname === '/portal/self-service') {
        history.replaceState(null, null, window.location.pathname);
    } else {
        window.location.hash = tab;
    }

    localStorage.setItem('ess_module_title', name);
    localStorage.setItem('ess_active_level', 'workspace');

    essActivateTab(tab);
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

function essOpenHub() {
    var hub = document.getElementById('ess_level_hub');
    var ws = document.getElementById('ess_level_workspace');
    var headerTitle = document.getElementById('ess_top_header_title');

    if (ws) ws.style.display = 'none';
    if (hub) hub.style.display = 'block';
    if (headerTitle) {
        headerTitle.innerText = 'البوابة الإلكترونية';
    }

    if (window.location.hash) {
        history.replaceState(null, null, ' ');
    }
    localStorage.setItem('ess_active_level', 'hub');
    localStorage.removeItem('ess_module_title');

    window.scrollTo({ top: 0, behavior: 'smooth' });
}

function essActivateTab(targetTab) {
    var links = document.querySelectorAll('.ess-nav-link');
    var panes = document.querySelectorAll('.ess-tab-pane');
    links.forEach(function(l) {
        if (l.getAttribute('data-tab') === targetTab) {
            l.classList.add('active');
        } else {
            l.classList.remove('active');
        }
    });
    panes.forEach(function(p) {
        if (p.id === targetTab) {
            p.classList.add('active');
            p.style.display = 'block';
        } else {
            p.classList.remove('active');
            p.style.display = 'none';
        }
    });

    // Handle Dynamic Sidebars
    var defaultSidebar = document.getElementById('sidebar_menu_default');
    var ctsSidebar = document.getElementById('sidebar_menu_cts');
    if (targetTab === 'tab_communications') {
        if (defaultSidebar) defaultSidebar.style.setProperty("display", "none", "important");
        if (ctsSidebar) ctsSidebar.style.setProperty("display", "flex", "important");
        if (window.loadCtsTransactions) window.loadCtsTransactions('all');
    } else {
        if (defaultSidebar) defaultSidebar.style.setProperty("display", "flex", "important");
        if (ctsSidebar) ctsSidebar.style.setProperty("display", "none", "important");
    }
    if (targetTab === 'tab_dashboard' && window.location.pathname === '/portal/self-service') {
        history.replaceState(null, null, window.location.pathname);
    } else {
        window.location.hash = targetTab;
    }
}

function essFilterCts(filterType, element) {
    if (filterType !== 'stats') {
        window.currentCtsFilter = filterType;
    }

    // Update active state in sidebar
    var ctsLinks = document.querySelectorAll('#sidebar_menu_cts .ess-nav-link');
    ctsLinks.forEach(function(l) {
        l.classList.remove('active');
    });
    if (element) {
        element.classList.add('active');
    }

    var dataView = document.getElementById('cts_data_view');
    var statsView = document.getElementById('cts_stats_view');

    if (filterType === 'stats') {
        if (dataView) dataView.style.display = 'none';
        if (statsView) statsView.style.display = 'block';
        // Reload stats specifically
        if (window.loadCtsTransactions) window.loadCtsTransactions(window.currentCtsFilter || 'all');
    } else {
        if (dataView) dataView.style.display = 'block';
        if (statsView) statsView.style.display = 'none';
        // Call data loading function
        if (window.loadCtsTransactions) {
            window.loadCtsTransactions(filterType);
        }
    }
}

function essRestoreStateOnLoad() {
    var hash = window.location.hash.replace('#', '');
    var level = localStorage.getItem('ess_active_level');
    var title = localStorage.getItem('ess_module_title') || 'الخدمة الذاتية';

    if (hash && hash.indexOf('tab_') === 0) {
        essOpenWorkspace(hash, title);
    } else if (level === 'workspace' && window.location.pathname === '/portal/self-service') {
        essOpenWorkspace('tab_dashboard', title);
    } else {
        essOpenHub();
    }
}

document.addEventListener('DOMContentLoaded', essRestoreStateOnLoad);
window.addEventListener('hashchange', essRestoreStateOnLoad);

body.script:
document.addEventListener('click', function(e) {
    var dd = document.getElementById('ess_app_dropdown');
    var btn = document.getElementById('ess_btn_app_switcher');
    if (dd && btn && !btn.contains(e.target) && !dd.contains(e.target)) {
        dd.classList.remove('ess-dropdown-open');
    }
    var np = document.getElementById('ess_notif_panel');
    var nb = document.getElementById('ess_notification_bell');
    if (np && nb && !nb.contains(e.target) && !np.contains(e.target)) {
        np.classList.remove('ess-notif-open');
    }
});
